import{_ as t,o as s,c as e,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 2 章 第一次对话：把需求讲清楚","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md"}'),n={name:"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md"};function l(d,a,i,p,r,c){return s(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="第-2-章-第一次对话-把需求讲清楚" tabindex="-1">第 2 章 第一次对话：把需求讲清楚 <a class="header-anchor" href="#第-2-章-第一次对话-把需求讲清楚" aria-label="Permalink to &quot;第 2 章 第一次对话：把需求讲清楚&quot;">​</a></h1><h2 id="_2-1-为什么-讲清楚-这么重要" tabindex="-1">2.1 为什么&quot;讲清楚&quot;这么重要 <a class="header-anchor" href="#_2-1-为什么-讲清楚-这么重要" aria-label="Permalink to &quot;2.1 为什么&quot;讲清楚&quot;这么重要&quot;">​</a></h2><p>同一个问题，两种问法：</p><ul><li>模糊版：&quot;帮我把这个文档弄一下。&quot;</li><li>清晰版：&quot;请阅读 docs/report.md，把第三节的数据更新为 data/q3.csv 里的最新数据，并输出为 docs/report_v2.md。&quot;</li></ul><p>同样的我，前者只能猜，后者能一次做对。**提示词的质量，决定交付的质量。**这不是玄学，而是信息论：你不给我验收标准，我就只能自己发明验收标准。</p><h2 id="_2-2-一个好任务的四个要素" tabindex="-1">2.2 一个好任务的四个要素 <a class="header-anchor" href="#_2-2-一个好任务的四个要素" aria-label="Permalink to &quot;2.2 一个好任务的四个要素&quot;">​</a></h2><p>把任何需求套进这个模板：</p><table tabindex="0"><thead><tr><th>要素</th><th>问题</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>你要什么结果？</td><td>一份 Q3 运营复盘报告</td></tr><tr><td>输入</td><td>资料在哪？</td><td>data/q3.csv、docs/template.md</td></tr><tr><td>约束</td><td>有什么限制？</td><td>不超过 3 页、用中文、保留表格</td></tr><tr><td>验收</td><td>怎么算完成？</td><td>数据与 csv 一致，有结论有建议</td></tr></tbody></table><p>写进一句话里，就是：</p><blockquote><p>&quot;阅读 data/q3.csv 和 docs/template.md，生成一份中文 Q3 运营复盘，不超过 3 页，数据必须与 csv 一致，最后给出 3 条建议。&quot;</p></blockquote><h2 id="_2-3-一次成功的对话流程" tabindex="-1">2.3 一次成功的对话流程 <a class="header-anchor" href="#_2-3-一次成功的对话流程" aria-label="Permalink to &quot;2.3 一次成功的对话流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：给任务（四要素尽量齐）</span></span>
<span class="line"><span>我：① 复述理解 → ② 指出缺信息（如果有）→ ③ 开始执行</span></span>
<span class="line"><span>你：检查中间产物，提出修改</span></span>
<span class="line"><span>我：修订 → 交付</span></span></code></pre></div><p><strong>重要</strong>：如果我的复述和你想要的不一致，立刻纠正我，不要让我一路错下去。</p><h2 id="_2-4-常见沟通误区" tabindex="-1">2.4 常见沟通误区 <a class="header-anchor" href="#_2-4-常见沟通误区" aria-label="Permalink to &quot;2.4 常见沟通误区&quot;">​</a></h2><ul><li>❌ 一次丢太多任务：&quot;帮我做 A、B、C、D，还要 E。&quot; → ✅ 拆开，一次一个。</li><li>❌ 只给目标不给输入：&quot;分析一下我们的销售。&quot; → ✅ &quot;分析 data/sales.csv，按地区汇总，找出下滑前三的区域。&quot;</li><li>❌ 验收标准太虚：&quot;写好一点。&quot; → ✅ &quot;结构用总分总，结论放开头，每条建议配数据。&quot;</li></ul><h2 id="_2-5-指令模板速用" tabindex="-1">2.5 指令模板速用 <a class="header-anchor" href="#_2-5-指令模板速用" aria-label="Permalink to &quot;2.5 指令模板速用&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：</span></span>
<span class="line"><span>目标：{你要的结果}</span></span>
<span class="line"><span>输入：{文件/目录/资料位置}</span></span>
<span class="line"><span>约束：{格式/长度/语言/风格}</span></span>
<span class="line"><span>验收：{怎么算完成}</span></span></code></pre></div><p>把这段模板存下来（或者让我存进记忆），以后每次都用它。</p><h2 id="_2-6-练习" tabindex="-1">2.6 练习 <a class="header-anchor" href="#_2-6-练习" aria-label="Permalink to &quot;2.6 练习&quot;">​</a></h2><ol><li>用四要素模板，向我提出一个你手头的真实任务。</li><li>让我复述一遍你的任务，检查理解是否一致。</li><li>如果我有遗漏，补上，再让我开始。</li></ol><blockquote><p>小结：<strong>讲清楚需求，不是麻烦我，而是帮助你自己。</strong> 一次说清，胜过十轮修改。</p></blockquote>`,21)])])}const _=t(n,[["render",l]]);export{h as __pageData,_ as default};
